let idempotencyKey = pm.environment.get("idempotencyKey");

if (!idempotencyKey) {
    idempotencyKey = pm.variables.replaceIn("{{$guid}}");
    pm.environment.set("idempotencyKey", idempotencyKey);

    console.log("Generated new Idempotency-Key:", idempotencyKey);
} else {
    console.log("Reusing Idempotency-Key:", idempotencyKey);
}

const success = pm.response.code >= 200 && pm.response.code < 300;

if (success) {
    const usedKey = pm.environment.get("idempotencyKey");

    console.log("Request succeeded with Idempotency-Key:", usedKey);

    pm.environment.unset("idempotencyKey");
}

