        workspaceId: "147e9db6-2e82-4ad9-9821-0c94b56b7d24"
        includeSimilarity: true
        includeAssociation: true
        minScore: 0.5
        minConfidence: 0.3
        sprintId: null
        backlogId: null
        source: "BATCH"
    ) {
        nodes {
            id
            label
            type
            priority
        }
        edges {
            from
            to
            type
            score
            confidence
            lift
        }
    }
}

