query WorkspaceGraph($workspaceId: ID!, $sprintId: ID, $backlogId: ID, $source: String, $includeSimilarity: Boolean, $includeAssociation: Boolean, $minScore: Float, $minConfidence: Float) {
  workspaceGraph(workspaceId: $workspaceId, sprintId: $sprintId, backlogId: $backlogId, source: $source,
    includeSimilarity: $includeSimilarity, includeAssociation: $includeAssociation,
    minScore: $minScore, minConfidence: $minConfidence) {
    nodes { id label type roles degree betweenness priority graphRelevanceScore duplicateScore }
    edges { from to type score confidence lift storyId storyIds weight sprintId backlogId source }
  }
}

